/* Own minimal Borlabs Cookie v2 simulator for integration tests (no vendor code). Mimics public identifiers only:
   window.BorlabsCookie, #BorlabsCookieBox ._brlbs-box-wrap, data-cookie-* links, cookie "borlabs-cookie". */
(function () {
  function getCookie(name) {
    var parts = document.cookie.split(';');
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i].trim();
      if (p.indexOf(name + '=') === 0) return decodeURIComponent(p.slice(name.length + 1));
    }
    return null;
  }
  // `sim.groups`: the optional groups the installation has; Borlabs stores only those, so "accept all" lists no other.
  var cfg = (window.borlabsCookieConfig && window.borlabsCookieConfig.sim) || {};
  var SERVICES = { statistics: ['google-analytics'], marketing: ['facebook-pixel'], 'external-media': ['youtube'] };
  var groups = cfg.groups || ['statistics', 'marketing', 'external-media'];
  function save(all) {
    var consents = { essential: ['borlabs-cookie'] };
    if (all) for (var i = 0; i < groups.length; i++) consents[groups[i]] = SERVICES[groups[i]];
    var v = JSON.stringify({ consents: consents, domainPath: location.host + '/', expires: 'Fri, 30 Oct 2027 00:00:00 GMT', uid: 'anonymous', version: '1' });
    document.cookie = 'borlabs-cookie=' + encodeURIComponent(v) + '; path=/; max-age=31536000; SameSite=Lax';
  }
  window.BorlabsCookie = { checkCookieConsent: function () { return !!getCookie('borlabs-cookie'); } };
  if (getCookie('borlabs-cookie')) return;
  var box = document.createElement('div');
  box.id = 'BorlabsCookieBox';
  box.innerHTML =
    '<div class="_brlbs-bar-wrap" style="position:fixed;left:0;right:0;bottom:0;z-index:999999;background:#fff;color:#222;padding:16px;font:15px/1.4 sans-serif;box-shadow:0 -2px 10px rgba(0,0,0,.3)">' +
    '<div class="_brlbs-bar" role="dialog" aria-label="Cookie-Hinweis">' +
    '<p>Wir nutzen Cookies auf unserer Website. Einige von ihnen sind essenziell. <a href="/datenschutz.html">Datenschutzerklärung</a></p>' +
    '<p><a href="#" class="_brlbs-btn _brlbs-btn-accept-all" data-cookie-accept-all style="display:inline-block;padding:10px 16px;background:#f7f7f7;color:#555;text-decoration:none">Alle akzeptieren</a> ' +
    '<a href="#" class="_brlbs-refuse-btn" data-cookie-refuse style="color:#555">Nur notwendige Cookies</a> ' +
    '<a href="#" class="_brlbs-manage" data-cookie-individual style="color:#555">Individuelle Datenschutzeinstellungen</a></p>' +
    '</div></div>';
  function show() {
    document.body.appendChild(box);
    function close(all, ev) { ev.preventDefault(); save(all); box.remove(); }
    box.querySelector('[data-cookie-accept-all]').addEventListener('click', function (ev) { close(true, ev); });
    box.querySelector('[data-cookie-refuse]').addEventListener('click', function (ev) { close(false, ev); });
  }
  if (document.body) show(); else document.addEventListener('DOMContentLoaded', show);
})();
